// Insights: the Logbuch dashboard (dashboard.html, regenerated by /daily) shown inside Carl.
import { $ } from "../core/dom.js";
import { onShow } from "../core/router.js";

const SRC = "/dashboard.html";
let loaded = false;
let resizeObs = null;

function fitHeight(frame) {
  try {
    const doc = frame.contentDocument;
    if (doc && doc.body) frame.style.height = Math.max(480, doc.documentElement.scrollHeight) + "px";
  } catch { /* cross-origin: keep min-height */ }
}

async function load(force = false) {
  const frame = $("dashFrame");
  if (loaded && !force) return;
  $("dashSkeleton").hidden = false;
  $("dashError").hidden = true;
  frame.hidden = true;
  try {
    const res = await fetch(SRC, { method: "HEAD", cache: "no-store" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
  } catch {
    $("dashSkeleton").hidden = true;
    $("dashError").hidden = false;
    return;
  }
  frame.onload = () => {
    $("dashSkeleton").hidden = true;
    frame.hidden = false;
    loaded = true;
    fitHeight(frame);
    try {
      const doc = frame.contentDocument;
      const gen = doc.body.textContent.match(/Generated (\d{4}-\d{2}-\d{2})/);
      $("dashMeta").textContent = gen ? `Last review: ${new Date(gen[1] + "T12:00").toLocaleDateString([], { weekday: "short", day: "numeric", month: "short" })}` : "Updated after each review";
      resizeObs?.disconnect();
      resizeObs = new ResizeObserver(() => fitHeight(frame));
      resizeObs.observe(doc.body);
    } catch { /* ignore */ }
  };
  frame.src = SRC + (force ? `?t=${Date.now()}` : "");
}

export function initInsights() {
  onShow("insights", () => load());
  $("dashReloadBtn").addEventListener("click", () => load(true));
  $("dashRetryBtn").addEventListener("click", () => load(true));
}
